const storage = {}; // giả lập localStorage

function save(key, value) {
  storage[key] = JSON.stringify(value);
}

function load(key, fallback) {
  return key in storage ? JSON.parse(storage[key]) : fallback;
}

console.log(load("cfg", { dark: false }));
save("cfg", { dark: true });
console.log(load("cfg", { dark: false }));
